import type {FC} from 'react';
import React, {memo} from 'react';

import {type IconData, useColorGenerator, useThemeType} from '@gravity-ui/uikit';

import {IconRefuge} from '../IconRefuge';

import {cnEntityIcon} from './EntityIcon.classname';

import './EntityIcon.scss';

export type EntityIconProps = {
    data: IconData;
    className?: string;
    id?: number | string;
    type?: string;
    refugeSize?: number;
    size?: number;
    alpha?: number;
    withBackground?: boolean;
    radius?: 'm' | 'l';
    colorAlpha?: number;
};

export const EntityIcon: FC<EntityIconProps> = memo(
    ({
        data,
        className,
        id,
        type,
        refugeSize = 24,
        size = 16,
        alpha = 0.15,
        withBackground = true,
        radius = 'm',
        colorAlpha = 1,
    }) => {
        const theme = useThemeType();

        const randomColor = useColorGenerator({seed: id !== undefined ? String(id) : ' ', theme});

        const color = `rgba(${randomColor.rgb.r},${randomColor.rgb.g},${randomColor.rgb.b},${colorAlpha})`;
        const backgroundColor = `rgba(${randomColor.rgb.r},${randomColor.rgb.g},${randomColor.rgb.b},${alpha})`;

        const containerStyle: {
            background?: string;
            color?: string;
        } = {};

        if (withBackground) {
            containerStyle.background = backgroundColor;
            containerStyle.color = color;
        } else {
            containerStyle.color = backgroundColor;
        }

        return (
            <IconRefuge
                data={data}
                containerClassName={cnEntityIcon({type, radius}, className)}
                refugeSize={refugeSize}
                size={size}
                containerStyle={containerStyle}
            />
        );
    },
);

EntityIcon.displayName = 'EntityIcon';
